// oe state notification unit test: when not consumed, each type keeps only its first queue position; after a pop a new change is queued again.
// The three messages only signal "query the current state" and carry no historical value. Expected order/state are hand-written, not generated by the implementation.
// The notification event set and cleared under the queue lock (plan item 157); cleared after unlocking (-DDM_TEST_OE_EVENT_UNLOCKED): 1 fails.
// The starting mode (plan item 62d); the profile's iOS mode not read (-DDM_TEST_OPMODE_NO_IOS): 1 fails.
#ifndef HLE_OE_SOURCE
#define HLE_OE_SOURCE "../hle/hle_oe.c"
#endif
#include HLE_OE_SOURCE
#include <signal.h>
#include <sys/wait.h>
uint64_t now_ns(void) { return 0; }
module_t g_mod[MAX_MOD]; int g_nmod;
uint64_t guest_ns(void) { return 0; }
static _Atomic int g_ev;   // the notification event's state (plan item 157)
static void ev_clear(void *g) { (void)g; atomic_store(&g_ev, 0); }
void *guest_sym(const char *name) { return !strcmp(name, "_ZN2nn2os16ClearSystemEventEPNS0_15SystemEventTypeE") ? (void *)ev_clear : NULL; }
void hle_bind_system_event(void *g, int autoclear) { (void)g; (void)autoclear; }
void hle_signal_system_event(void *g) { (void)g; atomic_store(&g_ev, 1); }
module_t *module_of(const void *p) { (void)p; return NULL; }
char dm_hcall_ret[4];   // host/runtime/hstack.S in the host (DM_GUEST_RA compares with it)
static int g_hold = -1, g_hook_rate = 30, g_hook_on = -1; static uint64_t g_hook_ra;
void nvn_fps_hold(int fps) { g_hold = fps; }   // gfx/nvn/hle_nvn.c in the host
int dm_game_inactivity_fps(int on, uint64_t ra) { g_hook_on = on; g_hook_ra = ra; return on ? g_hook_rate : 0; }   // the game's (games/totk/movie_fps.c)
static int checks, fails;
#define CHECK(c, s) do { checks++; int ok = !!(c); fails += !ok; printf("%s %s\n", ok ? "ok" : "FAIL", s); } while (0)
static void reset(void) { g_mqh = g_mqn = 0; g_focus = 1; g_opmode = 1; g_ntf_opmode = g_ntf_perfmode = 0; }
static int pop_is(uint32_t want) { uint32_t m = 999; return h_oe_TryPopMsg(&m) && m == want; }
static int empty(void) { uint32_t m = 999; return !h_oe_TryPopMsg(&m) && m == 999; }
static int child_kind;
static void abort_exit(int sig) { (void)sig; dprintf(2, "[red] t_oe child kind=%d: 10 s watchdog timeout\n", child_kind); _exit(97); } // the old-version die in the child process can be checked, avoiding a crash report or core
static void *focus_burst(void *p) { (void)p; for (int i = 0; i < 17; i++) { dm_focus_set(2); dm_focus_set(1); } return NULL; }
static void *mode_burst(void *p) { (void)p; for (int i = 0; i < 17; i++) dm_set_opmode(i % 2); return NULL; }
static pthread_t g_gap_th;
static void *push_focus(void *p) { (void)p; dm_focus_set(2); return NULL; }
static void gap_push(void) { pthread_create(&g_gap_th, NULL, push_focus, NULL); usleep(50000); }   // another thread pushes while the pop is between check and clear
static pthread_mutex_t stage_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t stage_cond = PTHREAD_COND_INITIALIZER;
static int stage, interleaved_ok;
static void stage_set(int n) { pthread_mutex_lock(&stage_lock); stage = n; pthread_cond_broadcast(&stage_cond); pthread_mutex_unlock(&stage_lock); }
static void stage_wait(int n) { pthread_mutex_lock(&stage_lock); while (stage < n) pthread_cond_wait(&stage_cond, &stage_lock); pthread_mutex_unlock(&stage_lock); }
static void *consume_interleaved(void *p) {
    (void)p; stage_wait(1); int ok = pop_is(15); stage_set(2); // popped but not yet queried: let the producer update exactly here
    stage_wait(3); interleaved_ok = ok && h_oe_GetFocus() == 1 && pop_is(15) && pop_is(30) && pop_is(31) && empty() && h_oe_GetOpMode() == 0 && h_oe_GetPerfMode() == 0;
    return NULL;
}
static int child_burst(int kind) {
    fflush(stdout); pid_t p = fork(); if (p < 0) return 0;
    if (!p) {
        child_kind = kind; signal(SIGABRT, abort_exit); signal(SIGALRM, abort_exit); alarm(10); reset();
        g_ntf_opmode = g_ntf_perfmode = 1;
        if (kind == 0) { focus_burst(NULL); _exit(h_oe_GetFocus() == 1 && pop_is(15) && empty() ? 0 : 1); }
        if (kind == 1) { mode_burst(NULL); _exit(h_oe_GetOpMode() == 0 && h_oe_GetPerfMode() == 0 && pop_is(30) && pop_is(31) && empty() ? 0 : 1); }
        if (kind == 3) {
            pthread_t c; pthread_create(&c, NULL, consume_interleaved, NULL);
            dm_focus_set(2); stage_set(1); stage_wait(2);
            dm_focus_set(1); dm_set_opmode(0); stage_set(3); pthread_join(c, NULL);
            _exit(interleaved_ok ? 0 : 1);
        }
        pthread_t f, m; pthread_create(&f, NULL, focus_burst, NULL); pthread_create(&m, NULL, mode_burst, NULL);
        pthread_join(f, NULL); pthread_join(m, NULL);
        uint32_t msg; int nf = 0, no = 0, np = 0, order = 1;
        while (h_oe_TryPopMsg(&msg)) { if (msg == 15) nf++; else if (msg == 30) no++; else if (msg == 31) { order &= no == 1; np++; } else order = 0; }
        _exit(nf == 1 && no == 1 && np == 1 && order && h_oe_GetFocus() == 1 && h_oe_GetOpMode() == 0 ? 0 : 1);
    }
    int st; if (waitpid(p, &st, 0) != p) return 0;
    return WIFEXITED(st) && WEXITSTATUS(st) == 0;
}
int main(void) {
    unsetenv("DM_OE_SCRIPT"); reset();
    CHECK(empty(), "empty queue at start: false, output untouched");
    dm_focus_set(1); dm_set_opmode(1); CHECK(empty(), "no notice for an unchanged state");
    dm_focus_set(3); CHECK(h_oe_GetFocus() == 3, "background state 3 can be queried before the pop");
    CHECK(pop_is(15) && empty(), "background change: notice 15 exactly once");
    dm_focus_set(2); dm_focus_set(1);
    CHECK(pop_is(15) && empty() && h_oe_GetFocus() == 1, "focus lost / regained before the pop merge; the query gives the final focus 1");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1;
    dm_focus_set(2); dm_set_opmode(0); dm_focus_set(3); dm_set_opmode(1);
    CHECK(pop_is(15) && pop_is(30) && pop_is(31) && empty(), "first positions of the three kinds, FIFO 15,30,31; repeats keep their place");
    CHECK(h_oe_GetFocus() == 3 && h_oe_GetOpMode() == 1 && h_oe_GetPerfMode() == 1, "repeated notices keep no stale value; the queries give the latest 3/1/1");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1;
    dm_set_opmode(0); dm_focus_set(2); dm_set_opmode(1);
    CHECK(pop_is(30) && pop_is(31) && pop_is(15) && empty(), "mode changing first: FIFO 30,31,15, the pair keeps its order");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1;
    dm_focus_set(2); CHECK(pop_is(15), "pop the focus notice first");
    dm_set_opmode(0); dm_focus_set(1);
    CHECK(pop_is(30) && pop_is(31) && pop_is(15) && empty(), "a change after the pop notifies again, queued after the pending mode notices");
    CHECK(h_oe_GetFocus() == 1, "current focus after regaining = 1");
    reset(); dm_set_opmode(0);
    CHECK(empty() && h_oe_GetOpMode() == 0, "notices off: state updated, nothing queued");
    h_oe_SetOpModeNtf(0x100); h_oe_SetPerfModeNtf(0x101); dm_set_opmode(1);
    CHECK(pop_is(31) && empty(), "the notice bool reads the low 8 bits only; performance mode alone sends 31 only");
    h_oe_SetOpModeNtf(0x101); h_oe_SetPerfModeNtf(0x100); dm_set_opmode(0);
    CHECK(pop_is(30) && empty(), "operation mode alone sends 30 only");
    reset(); mq_push(16); mq_push(16);
    CHECK(pop_is(16) && pop_is(16) && empty(), "per-event notice 16 is not merged, both kept FIFO");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1; dm_set_opmode(0);
    CHECK(pop_is(30), "pop 30 of the mode pair, 31 not popped yet");
    dm_set_opmode(1);
    CHECK(pop_is(31) && pop_is(30) && empty() && h_oe_GetOpMode() == 1, "a new change across the pop: the old 31 keeps its place, the popped 30 is queued again, final mode 1");
    CHECK(child_burst(0), "34 focus changes across the old 32 slots: no abort, final 1 / one 15");
    CHECK(child_burst(1), "17 mode changes across the old 32 slots: no abort, final 0 / 30,31");
    CHECK(child_burst(2), "two concurrent producers: one of each kind, 30 before 31, final focus 1 / mode 0");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1; int rotated = 1;
    for (int i = 0; i < 31; i++) { dm_focus_set(2 - i % 2); rotated &= pop_is(15) && empty(); }
    CHECK(rotated, "31 single pops move the ring head to the last slot");
    dm_focus_set(1); dm_set_opmode(0); dm_focus_set(3); dm_set_opmode(1);
    CHECK(pop_is(15) && pop_is(30) && pop_is(31) && empty(), "after wrapping the 32 slots: still deduplicated, first order 15,30,31 kept");
    CHECK(child_burst(3), "a change between the pop and the query is not lost: final focus 1 / mode 0");
    // The exit-request section's depth (a quit waits while it is above 0): nested, and a Leave without an Enter does not go below 0
    CHECK(!dm_oe_exit_section(), "exit-request section: outside at first");
    h_oe_EnterExitSec(); h_oe_EnterExitSec(); h_oe_LeaveExitSec(); CHECK(dm_oe_exit_section(), "entered twice, left once: still inside");
    h_oe_LeaveExitSec(); CHECK(!dm_oe_exit_section(), "left twice: outside");
    h_oe_LeaveExitSec(); h_oe_EnterExitSec(); CHECK(dm_oe_exit_section(), "a Leave too many is ignored: one Enter is inside again");
    h_oe_LeaveExitSec();
    // The frame rate held while the game extends the user inactivity time, as the game hook says (plan item 130; Tears of the Kingdom's pre-rendered
    // movies). The old stub that ignored the call (-DDM_TEST_INACTIVITY_NOOP) fails 8
    unsetenv("DM_INACTIVITY_FPS");
    h_oe_Inactivity(1); CHECK(g_hold == 30 && g_hook_on == 1 && g_hook_ra, "inactivity time extended (true): the hook gets it with the caller, its 30 is held");
    h_oe_Inactivity(0); CHECK(g_hold == 0 && g_hook_on == 0, "false: hold released");
    h_oe_Inactivity(0x101); CHECK(g_hold == 30, "a bool is its low 8 bits: 0x101 is true");
    h_oe_Inactivity(0x100); CHECK(g_hold == 0, "... and 0x100 false");
    h_oe_InactivityU(1); CHECK(g_hold == 30, "the Unsafe variant holds as well"); h_oe_InactivityU(0);
    g_hook_rate = 0; h_oe_Inactivity(1); CHECK(g_hold == 0 && g_hook_on == 1, "the hook gives 0 (a real-time cutscene): no hold"); g_hook_rate = 30;
    setenv("DM_INACTIVITY_FPS", "0", 1); h_oe_Inactivity(1); CHECK(g_hold == 0, "DM_INACTIVITY_FPS=0: no hold");
    setenv("DM_INACTIVITY_FPS", "24", 1); h_oe_Inactivity(1); CHECK(g_hold == 24, "DM_INACTIVITY_FPS=24 replaces the hook's rate"); h_oe_Inactivity(0); unsetenv("DM_INACTIVITY_FPS");
    // The notification event (plan item 157): a message pushed while TryPop finds the queue empty and clears the event (between its check and its
    // clear, g_oe_test_clear_gap) leaves the event signalled with the message queued; cleared after unlocking (-DDM_TEST_OE_EVENT_UNLOCKED) it ends clear
    {   reset(); h_oe_GetMsgEv(); atomic_store(&g_ev, 0);
        g_oe_test_clear_gap = gap_push; uint32_t m = 999; int got = h_oe_TryPopMsg(&m); g_oe_test_clear_gap = NULL; pthread_join(g_gap_th, NULL);
        CHECK(!got && g_mqn == 1 && atomic_load(&g_ev) == 1, "event signalled with the message pushed during an empty pop's clear");
        CHECK(pop_is(15) && empty() && atomic_load(&g_ev) == 0, "... popped: the queue empty and the event clear"); }
    // The starting mode (plan item 62d): DM_OPMODE when set; on iOS handheld for a profile that says so; else console
    CHECK(dm_opmode_start(NULL, 1, 1) == 0, "iOS, a profile with ios_mode handheld: handheld");
    CHECK(dm_opmode_start(NULL, 1, 0) == 1 && dm_opmode_start(NULL, 0, 1) == 1, "... without it, or on the Mac: console");
    CHECK(dm_opmode_start("1", 1, 1) == 1 && dm_opmode_start("0", 0, 0) == 0, "DM_OPMODE over both");
    printf("t_oe: %d checks, %d failed\n", checks, fails); return fails != 0;
}
